insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2026-03-30-hypertrophy-reverse-pyramid', 2, 'Hypertrophy Reverse Pyramid', 'reverse-pyramid', '2026-03-30', 6, 'coach', 'A 6-week intensity block: heavy reverse pyramids on the first big lift for each muscle plus drop sets, to push harder after the volume block that came before it.', '[{"title": "Goal", "body": "Raise the intensity after a volume phase: lift your heaviest weights while fresh, then add deep fatigue with lighter sets and drop sets. In the rotation this block followed the flat-pyramid volume block and came before the heavy strength block."}, {"title": "How it works", "body": "The first big lift for each muscle is a reverse pyramid: the heaviest set comes first at 8 reps, then the weight comes down as reps go up to 10, 12 and 15. Next come drop sets: do 12 reps near failure, cut the weight by about 20-30% and do 12 more with no rest. Lead lifts include the incline barbell bench press, the neutral-grip dumbbell overhead press and heels-elevated high-bar squats, with about 90 seconds of rest."}, {"title": "A days vs B days", "body": "A days run the reverse pyramid at 8-10-12-15 and drop sets at 12+12; B days use the same exercises at 10-12-15-20 and 15+15 with lighter weights. A days build heavy-load strength and size, while B days add volume and pump with less strain on the joints."}, {"title": "How to progress", "body": "Progress each pyramid set''s weight separately: when you hit all the reps of a set cleanly, add a small step to that set next week. For drop sets, raise the starting weight once both halves are completed. If you miss reps, keep the weight and aim for one more rep next time."}, {"title": "What to expect", "body": "Sessions feel harder and shorter than in a volume block, with a burning pump during drop sets and real fatigue by the end. The first heavy set takes focus and a good warm-up. Expect to feel stronger on the lead lifts by weeks 4-6."}, {"title": "Key tips", "body": "Warm up with a few lighter ramp-up sets before the first reverse-pyramid set, since it is the hardest. Use machines and cables for drop sets so changing the weight is quick. Stop the set if your form breaks down rather than grinding out ugly reps."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
