insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2026-07-06-hypertrophy-pyramid', 4, 'Hypertrophy Pyramid', 'ascending-pyramid', '2026-07-06', 6, 'coach', 'A 6-week volume block with ascending pyramids: the weight goes up each set as reps go down, followed by supersets, using the strength gained in the previous heavy block.', '[{"title": "Goal", "body": "Turn the strength built in the heavy block into more muscle by pairing high volume with one heavy top set per lift. In the rotation it followed the strength-hypertrophy block and came before the second reverse-pyramid block."}, {"title": "How it works", "body": "The first lift for each muscle is an ascending pyramid: start light at 15 reps, then add weight each set as reps drop to 12, 10 and 8, so the last set is the heaviest. Lead lifts include the plate-loaded wide-grip chest press, the neutral-grip shoulder press and heels-elevated squats, with up to 2 minutes of rest. After that come supersets of a compound and an isolation exercise for the same muscle, with about 10 seconds between them."}, {"title": "A days vs B days", "body": "A days run the pyramid at 15-12-10-8 and supersets at 10 + 15 reps; B days use the same exercises at 20-15-12-10 and 12 + 20 with lighter weights. A days reach a heavier top set, while B days add more total reps and pump."}, {"title": "How to progress", "body": "Progress each pyramid set''s weight separately: when a set''s reps are completed cleanly, add a small step to that set next time, especially the final 8-rep set. For supersets, raise the weight of each exercise once all its reps are done. If you miss reps, keep the weight and beat it next week."}, {"title": "What to expect", "body": "The light opening sets feel easy and act as a warm-up, and the effort builds to a hard final set. Supersets bring a strong pump and keep sessions dense. Expect solid fatigue by the end of each workout, especially on B days."}, {"title": "Key tips", "body": "Do not rush the early, lighter sets: use them to groove good technique for the heavier ones. Plan your weight jumps before the session so you are not guessing between sets. Keep the 10-second gap in supersets short."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
