insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2026-08-17-hypertrophy-reverse-pyramid', 5, 'Hypertrophy Reverse Pyramid', 'reverse-pyramid', '2026-08-17', 6, 'coach', 'A 6-week intensity block: reverse pyramids with the heaviest set first plus longer drop sets, revisiting the block 2 method with new exercises after the pyramid volume block.', '[{"title": "Goal", "body": "Push intensity again after a volume block: lift heavy while fresh, then build fatigue with lighter sets and long drop sets. It revisited the block 2 method with different exercise choices, followed the ascending-pyramid block and led into a new volume block."}, {"title": "How it works", "body": "Each muscle''s first big lift is a reverse pyramid: heaviest set first at 8 reps, then lighter as reps rise to 10, 12 and 15. Drop sets follow: 15 reps near failure, reduce the weight by about 20-30%, then 15 more with no rest. Lead lifts include the incline barbell bench press, the neutral-grip dumbbell overhead press and the hack squat, with about 90 seconds of rest, and a straight-set finisher closes each part."}, {"title": "A days vs B days", "body": "A days use 8-10-12-15 in the pyramid and 15+15 drop sets; B days use 10-12-15-20 and 20+20 with lighter weights. A days are about heavy loading, while B days bring very high reps, a big pump and less joint stress."}, {"title": "How to progress", "body": "Progress each pyramid set separately, adding a small step to a set once you hit all its reps with good form. For drop sets, raise the starting weight once both halves are completed. Aim to beat your block 2 numbers on any lifts the two blocks share."}, {"title": "What to expect", "body": "Expect hard, fatiguing sessions with an intense burn on the long drop sets, especially the 20+20 sets on B days. The heavy opening set needs focus and a proper warm-up. Strength on the lead lifts should climb steadily through the six weeks."}, {"title": "Key tips", "body": "Warm up with a few ramp-up sets before your first heavy set. Set up drop-set weights in advance on machines or cables so the change takes seconds. Keep form strict in the second half of each drop set instead of swinging the weight."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
