insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2026-10-05-hypertrophy-flat-pyramid-ii', 6, 'Hypertrophy Flat Pyramid II', 'flat-pyramid', '2026-10-05', 6, 'pt', 'A 6-week volume block: flat sets with the same reps and weight on every set, plus supersets. Chest is pressed at 30 degrees and flat, with high-to-low cable flies, to grow every part of the chest.', '[{"title": "Goal", "body": "Build muscle through plenty of quality, moderately heavy work after the intensity of block 5. It gives your joints a break from very heavy sets while still growing muscle, and it sets up the heavy strength block that comes next."}, {"title": "How it works", "body": "Every set of an exercise uses the same reps and weight, for example 4 x 12 on the 30-degree incline dumbbell press, the Smith machine shoulder press and the plate-loaded pendulum squat. After the main lift, two exercises are done as a superset: the first, about 10 seconds of rest, then the second, then 60-90 seconds of rest. On chest day that is a flat dumbbell press with high-to-low cable flies. New choices include the chest-supported T-bar row, Bulgarian split squats, reverse pec deck and cable crunches."}, {"title": "A days vs B days", "body": "A days use 10-12 reps per set (15 on finishers) with heavier weights; B days repeat the same exercises in the same order at 12-15 reps (20 on finishers) with lighter weights. A days give heavier, controlled work, while B days add volume and pump with less stress on the joints."}, {"title": "How to progress", "body": "Keep the weight the same for every set. When you complete all reps of all sets with good form and about one rep left in the tank, add the smallest step next time (about 1-2.5 kg upper body, 2.5-5 kg lower body). If you fall short, keep the weight and aim for one more rep next week. Track A and B days separately."}, {"title": "What to expect", "body": "Expect a strong pump and steady, manageable fatigue rather than very heavy sets. Supersets make sessions feel dense, and new exercises like Bulgarian split squats may cause extra soreness in the first week or two. Strength should rise gradually from week to week."}, {"title": "Key tips", "body": "Pick a starting weight you can hold for all four sets; it is fine if week 1 feels a little easy. Keep the 10-second gap inside supersets short: on chest day, set up a flat bench next to the cable station before you start. Learn the new exercises with moderate weights first before pushing them hard."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
