insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2026-11-16-strength-hypertrophy-ii', 7, 'Strength-Hypertrophy II', 'strength-hypertrophy', '2026-11-16', 6, 'pt', 'A 6-week strength block: heavy compound lifts in flat sets of 6 and 8 reps with 2-minute rests. Chest is pressed flat and at 30 degrees, to raise the weights you will use in blocks 8 and 9.', '[{"title": "Goal", "body": "Get stronger on the big compound lifts so the next two muscle-building blocks can be done with heavier weights. It follows the block 6 volume phase and mirrors the coach''s block 3, which worked well before a pyramid block."}, {"title": "How it works", "body": "Main lifts use flat sets with heavy weights and about 2 minutes of rest, for example 4 x 6 on the back squat, the flat Smith machine bench press and the seated barbell overhead press (upright seat). Secondary lifts like the 30-degree incline dumbbell press and wide-grip pull-ups use 8 reps; dips, the 30-degree chest-supported row and isolation work use 10. Each day has 6 exercises and no supersets or drop sets."}, {"title": "A days vs B days", "body": "A days use 6 reps on the main lifts with the heaviest loads; B days repeat the same exercises at 8 reps (secondary lifts at 10, isolation at 12) with a bit less weight. A days drive maximum strength, while B days add volume to support muscle growth."}, {"title": "How to progress", "body": "Keep the same weight for all sets. When you complete every set cleanly with about one rep in reserve, add the smallest step next time; small, steady jumps work best at low reps. For pull-ups and dips, add extra weight only once all bodyweight reps are easy. If you miss reps, repeat the weight until you own it."}, {"title": "What to expect", "body": "Sessions are slower and less pumpy, with longer rests, but each set feels heavy and demanding. Expect more whole-body tiredness after squats and rows than local burn. By weeks 5-6 your main lifts should be clearly heavier than at the start."}, {"title": "Key tips", "body": "Take the full 2-minute rest on the main lifts. Warm up with a few lighter ramp-up sets before your first working set, especially for back squats. Use safety pins or a spotter on heavy barbell work, set the bench angle before your warm-up sets, and learn new lifts like the JM press with light weights first."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
