insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2026-12-28-hypertrophy-pyramid-ii', 8, 'Hypertrophy Pyramid II', 'ascending-pyramid', '2026-12-28', 6, 'pt', 'A 6-week volume block with ascending pyramids and supersets: 45-degree incline and decline chest work, using the strength from block 7. Week 1 falls on the holidays and is a lighter week before full sessions resume.', '[{"title": "Goal", "body": "Turn the strength built in block 7 into more muscle with high volume and one heavy top set per lift. It also eases back in after the holidays and ten months of training, and it leads into the reverse-pyramid intensity of block 9."}, {"title": "How it works", "body": "The first lift for each muscle is an ascending pyramid: start light at 15 reps, then add weight each set as reps drop to 12, 10 and 8. Lead lifts include the 45-degree incline barbell press, the dumbbell shoulder press and the Smith machine squat, with up to 2 minutes of rest. Supersets follow about 10 seconds apart, such as decline dumbbell press with decline flies for the lower chest, and Y-raises with spider curls on a 45-degree bench."}, {"title": "A days vs B days", "body": "A days run the pyramid at 15-12-10-8 and supersets at 10 + 15 reps; B days use the same exercises at 20-15-12-10 and 12 + 20 with lighter weights. A days reach a heavier top set, while B days pile on reps and pump."}, {"title": "How to progress", "body": "Week 1 is lighter: do the same sessions but stop every set about 3 reps short of failure and skip the last set of each exercise. From week 2, train fully and progress each pyramid set''s weight separately, adding a small step once its reps are completed cleanly. For supersets, raise each exercise''s weight once all its reps are done."}, {"title": "What to expect", "body": "Week 1 should feel easy and refreshing, not like a test. From week 2 the light opening sets work as a warm-up, effort builds to a hard final set, and supersets bring a strong pump. Expect your top-set weights to beat block 4 on similar lifts."}, {"title": "Key tips", "body": "Resist the urge to go hard in week 1; the lighter week helps you start the year fresh. Plan your weight jumps for each pyramid set before the session. Set up the bench for each superset before you start it, and keep the 10-second gap short."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
