insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights) values ('block-2027-02-08-hypertrophy-reverse-pyramid-iii', 9, 'Hypertrophy Reverse Pyramid III', 'reverse-pyramid', '2027-02-08', 6, 'pt', 'A 6-week intensity block: heavy reverse pyramids on the main lifts plus drop sets, with a flat bench press, low-incline flies and 60-degree incline curls, using the strength from block 7 and volume from block 8.', '[{"title": "Goal", "body": "Push intensity after the block 8 volume phase: lift your heaviest weights while fresh, then add deep fatigue with lighter sets and drop sets. It uses the strength gained in block 7 and introduces free-weight lead lifts like the barbell bench press and front squat."}, {"title": "How it works", "body": "The first big lift for each muscle is a reverse pyramid: heaviest set first at 8 reps, then the weight comes down as reps rise to 10, 12 and 15. Next come drop sets: 12 reps near failure, cut the weight by about 20-30%, then 12 more with no rest. Lead lifts are the flat barbell bench press, the standing overhead press, 60-degree incline curls and the front squat, with about 90 seconds of rest (2 minutes on the front squat)."}, {"title": "A days vs B days", "body": "A days use 8-10-12-15 in the pyramid and 12+12 drop sets; B days use 10-12-15-20 and 15+15 with lighter weights. A days are about heavy loading, while B days add volume and pump with less strain on the joints."}, {"title": "How to progress", "body": "Progress each pyramid set separately, adding a small step to a set once you hit all its reps with good form. For drop sets, raise the starting weight once both halves are completed. If you miss reps, keep the weight and aim for one more rep next week."}, {"title": "What to expect", "body": "Sessions are hard and fatiguing, with a strong burn during drop sets. The first heavy set of each lead lift takes focus, and the front squat and standing press demand more balance than machines. Expect your lead lifts to climb steadily through the six weeks."}, {"title": "Key tips", "body": "Warm up with a few ramp-up sets before each first heavy set. Learn the front squat and standing overhead press with moderate weights in week 1 before pushing the pyramid. On 60-degree incline curls, let the arms hang fully at the bottom of each rep. Use machines and cables for drop sets so weight changes are quick."}]'::jsonb) on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
